      "text": "천 년 잠에서 깬 사람들이 동료 시몬의 시신을 찾아요. 등에 칼이 박힌 미라였고, 그의 테그미네는 153년 전에 멈춰 있었어요(p.14~18). 셸터는 밖에서 들어올 수 없고, 깨어난 사람은 혼자서 다시 잠들 수 없어요. 그러니 범인은 외부인이어야 하죠. 냉동고에서는 얼굴이 뭉개진 소년이 나오고(p.80), 이어 이리야마저 가슴에 칼을 맞고 숨져요(p.231). 이리야를 죽인 건 시몬과 똑같은 얼굴을 한 부족, 마크노아의 메가와 이프시였어요(p.328)."
