      "text": "마지막 장이 절벽을 다시 보여 줘요. 히데미는 얼굴을 보며 쏠 자신이 없어 등을 돌리게 했어요(p.348). 그때 우에쓰지가 사기의 진상을 털어놓으려 했고, 히데미는 그 말이 끝나기 전에 쏘았어요(p.349). 뒷말을 떠올리려다 그녀는 «생각을 멈췄다»(p.349). 그리고 한 겹 더, 나에는 유카와를 낳아 양자로 보낸 친어머니였어요(p.333~334). 이 모든 건 끝내 경찰에게 말해지지 않아요. 전부 아는 건 책을 덮은 당신이에요."
