   "excerpt": "고바야시 야스미의 호러 단편집 인수세공을 가제본으로 먼저 읽어보았습니다. 책을 펼치면 소설보다 먼저 “사기”의 한 구절이 나옵니다. 여태후가 척부인에게 끔찍한 형벌을 내리고, 그를 '인간돼지'라 불렀다는 이야기. 이 한 줄에서 벌써…… 가제본은 약 120페이지 분량이고, 인수 세공과 흡혈귀사냥 단편 두 편이 실려 있습니다. 인수세공은 굉장히 기괴한 바디호러 느낌이며, 흡혈귀 사냥은 시골의 여름괴담인데 굉장히 서늘한 느낌을 줍니다. 두 이야기 모두 '사람과 사람이 아닌 것의 경계'를 건드립니다 인수세공의 주인공은 유카이며, 흡혈귀사냥은 어른이 된 나의 시점에서 진행됩니다. 이야기는 이렇습니다."
