   "rating": 5,
   "plus": false,
   "gajebon": false,
   "deep": false,
   "slug": "살로메의-단두대",
   "excerpt": "이 시리즈의 1편 교수상회에서 보여준 가능성, 2편인 시계 도둑과 악인들에서 끌어올린 기대감이 마침내 이 번 작품에서 완벽하게 폭발합니다. 🪓🩸 유키하루오가 자신이 쌓아 올린 정점을 다시 한번 가볍게 돌파해 버렸습니다 📚 책 정보 약 600쪽 / 서장과 종장을 포함해 총 12개의 장으로 약간은 벽돌책 느낌입니다. 다소 두꺼운 분량이지만, 앞에서 쌓아올린 이야기가 10장 '단두대'에서 폭발하는 느낌을 받을 수 있습니다. 전혀 상관없어 보이는 연관도 없어 보이는 모든 퍼즐이 맞춰지는 후반부에 다다르면 경악을 금지 못할 것입니다. 🧱💨 🧩 이야기 화가 '이구치'가 그 어디에도 발표한 적 없는 미공개 그림 한 점."
